AP4_HdlrAtom::AP4_HdlrAtom(AP4_UI32 size, AP4_UI08 version, AP4_UI32 flags, AP4_ByteStream& stream) 
    : AP4_Atom(AP4_ATOM_TYPE_HDLR, size, version, flags)
{
    AP4_UI32  pre_defined;
    AP4_UI32  handler_type;
    AP4_UI32  reserved[4];

    // Read predefined fields
    stream.ReadBEUI32(pre_defined);
    stream.ReadBEUI32(handler_type);
    stream.ReadBEUI32(reserved[0]);
    stream.ReadBEUI32(reserved[1]);
    stream.ReadBEUI32(reserved[2]);
    stream.ReadBEUI32(reserved[3]);

    // Read handler name
    AP4_Size  name_size = size - (AP4_Atom::GetHeaderSize() + 20);
    if (name_size > 0) {
        AP4_String name;
        if (name_size == 1) {
            // Pascal string
            AP4_UI08 length;
            stream.ReadUI08(length);
            name = AP4_String((const char*)AP4_DataBuffer(length).Use(), length);
        } else {
            // C string
            name = AP4_String((const char*)AP4_DataBuffer(name_size).Use(), name_size);
        }
        m_handlerName = name;
    }
}

AP4_HdlrAtom::AP4_HdlrAtom(AP4_UI32 size, AP4_UI08 version, AP4_UI32 flags, AP4_ByteStream& stream)
    : AP4_Atom(AP4_ATOM_TYPE_HDLR, size, version, flags)
{
    AP4_UI32  pre_defined[3];
    AP4_UI32  handler_type;
    AP4_UI32  reserved[2];
    AP4_Size  pascal_length;
    AP4_String  handler_name;

    // Read pre-defined values
    stream.ReadUI32(pre_defined[0]);
    stream.ReadUI32(pre_defined[1]);
    stream.ReadUI32(pre_defined[2]);

    // Read handler type
    stream.ReadUI32(handler_type);

    // Read reserved values
    stream.ReadUI32(reserved[0]);
    stream.ReadUI32(reserved[1]);

    // Determine handler name based on atom size
    if (size > AP4_HDLR_ATOM_HEADER_SIZE) {
        // Check for pascal string
        stream.ReadUI16(pascal_length);
        if (pascal_length > 0) {
            handler_name.SetSize(pascal_length + 1);
            stream.ReadBytes(reinterpret_cast<AP4_Byte*>(handler_name), pascal_length);
            handler_name[pascal_length] = 0;
        } else {
            // C string
            AP4_Size c_string_length = size - AP4_HDLR_ATOM_HEADER_SIZE - 2;
            handler_name.SetSize(c_string_length + 1);
            stream.ReadBytes(reinterpret_cast<AP4_Byte*>(handler_name), c_string_length);
            handler_name[c_string_length] = 0;
        }
    }

    // Store handler type and name internally as needed
    m_handlerType = handler_type;
    m_handlerName = handler_name;
}

