    // Read reserved values
    stream.ReadUI32(reserved[0]);
    stream.ReadUI32(reserved[1]);

    // Determine how to read the handler name
    if (size > 20) {
        // Read Pascal string
        stream.ReadUI16(pascal_length);
        if (pascal_length > 0) {
            AP4_UI08* name = new AP4_UI08[pascal_length + 1];
