AP4_HdlrAtom::AP4_HdlrAtom(AP4_UI32 size, AP4_UI08 version, AP4_UI32 flags, AP4_ByteStream& stream) :
    AP4_Atom(AP4_ATOM_TYPE_HDLR, size, version, flags)
{
    AP4_UI32  pre_defined;
    AP4_UI32  handler_type;
    AP4_UI32  reserved[2];
    AP4_UI16  name_length;

    stream.ReadBE(pre_defined);
    stream.ReadBE(handler_type);
    stream.ReadBE(reserved, sizeof(reserved));

    stream.ReadBE(name_length);
    if (name_length > 0) {
        if (name_length == 1) {
            // Pascal string
            AP4_UI8 pascal_length;
            stream.Read(pascal_length);
            m_HandlerName.SetLength(pascal_length);
            stream.Read(m_HandlerName.UseData(), pascal_length);
            m_HandlerName.Append('\0');
        }
        else {
            // C string
            m_HandlerName.SetLength(name_length);
            stream.Read(m_HandlerName.UseData(), name_length);
            m_HandlerName[name_length] = '\0';
        }
    }
}

AP4_HdlrAtom::AP4_HdlrAtom(AP4_UI32 size, AP4_UI08 version, AP4_UI32 flags, AP4_ByteStream& stream) :
    AP4_Atom(AP4_ATOM_TYPE_HDLR, size, version, flags)
{
    AP4_UI32  pre_defined[3];
    AP4_UI32  handler_type;
    AP4_UI32  reserved[2];
    AP4_UI16  name_length;

    stream.ReadBE(pre_defined, sizeof(pre_defined));
    stream.ReadBE(&handler_type, sizeof(handler_type));
    stream.ReadBE(reserved, sizeof(reserved));

    stream.ReadBE(&name_length);
    if (size > 22) {
        m_handler_name.SetLength(name_length);
        stream.ReadBE(m_handler_name.UseData(), m_handler_name.Length());
        if (name_length > 0) {
            AP4_UI08 first_char = m_handler_name[0];
            if (first_char == 0) {
                // Pascal string: move data left by one and null-terminate
                m_handler_name.SetLength(m_handler_name.Length() - 1);
                memmove(m_handler_name.UseData(), m_handler_name.UseData() + 1, m_handler_name.Length());
                m_handler_name[m_handler_name.Length()] = 0;
            } else {
                // C string: ensure null-terminated
                m_handler_name.Append(0);
            }
        }
    }
}
